export type ParsedHarvestYieldAndCommitInstruction<
  TProgram extends string = typeof ANCHOR_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The crank signer executing the harvest. Must match the `jobs_account` in the global configuration. */
    crank: TAccountMetas[0];
    /** The global configuration account, checked to authorize the crank bot. */
    globalConfig: TAccountMetas[1];
    /** The prize pool state account, tracking deposit and prize status. */
    pool: TAccountMetas[2];
    /** The ticket registry account loader, holding all active and pending tickets. */
    ticketRegistry: TAccountMetas[3];
    /** The draw cycle account initialized for the current draw. */
    currentDrawCycle: TAccountMetas[4];
    /** Pool's $PST vault — read balance to calculate current value. */
    poolPstVault: TAccountMetas[5];
    /** Huma $PST mint — read supply for price calculation. */
    pstMint: TAccountMetas[6];
    humaPoolState: TAccountMetas[7];
    randomnessAccount: TAccountMetas[8];
    /** The SPL Token interface for the PST mint/vault. */
    pstTokenProgram: TAccountMetas[9];
    /** The Solana System Program. */
    systemProgram: TAccountMetas[10];
    eventAuthority: TAccountMetas[11];
    /** The YieldBonds program itself. */
    program: TAccountMetas[12];
  };
  data: HarvestYieldAndCommitInstructionData;
};

export function parseHarvestYieldAndCommitInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedHarvestYieldAndCommitInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      crank: getNextAccount(),
      globalConfig: getNextAccount(),
      pool: getNextAccount(),
      ticketRegistry: getNextAccount(),
      currentDrawCycle: getNextAccount(),
      poolPstVault: getNextAccount(),
      pstMint: getNextAccount(),
      humaPoolState: getNextAccount(),
      randomnessAccount: getNextAccount(),
      pstTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getHarvestYieldAndCommitInstructionDataDecoder().decode(
      instruction.data
    ),
  };
}
